import sys
from collections import Counter

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    g = [[int(x) for x in data[2 + i * c:2 + (i + 1) * c]] for i in range(r)]
    rows = [Counter(row) for row in g]
    cols = [Counter(g[i][j] for i in range(r)) for j in range(c)]
    EMPTY = 0

    def rest(C, a, L):
        # value shared by all other cells of a line, EMPTY if none, -1 if not uniform
        k = len(C)
        if k == 1:
            return a if L > 1 else EMPTY
        if k == 2 and C[a] == 1:
            for key in C:
                if key != a:
                    return key
        return -1

    total = 0
    for i in range(r):
        Ri = rows[i]
        gi = g[i]
        for j in range(c):
            a = gi[j]
            rv = rest(Ri, a, c)
            if rv == -1:
                continue
            cv = rest(cols[j], a, r)
            if cv == -1:
                continue
            if rv == EMPTY or cv == EMPTY or rv == cv:
                total += 1
    print(total)

